/**
 * The container image: `app/generated/Dockerfile`.
 *
 * This is the only artifact whose presence depends on *where* the app runs rather than on
 * what it does, so the tests here are about two things a reader cannot check by eye:
 *
 *   1. A spec that deploys nowhere as a container plans no image at all. An image nothing
 *      deploys would be regenerated byte-identically forever, which is how a dead file
 *      becomes permanent.
 *   2. The image runs the application that was generated, not a copy of it. The entrypoint
 *      names `app.main:app`, which belongs to the application and is never emitted here --
 *      a Dockerfile that invented an entrypoint would produce an image that builds and then
 *      answers nothing.
 *
 * Nothing asserts the bytes: a Dockerfile is prose plus a small set of directives, and a
 * byte pin would fail on a comment edit while a missing `USER` slipped through. Each test
 * therefore names one property the image has to keep.
 */

import { describe, expect, it } from 'vitest';

import { DOCKERFILE_PATH, emitDockerfile, hasContainerDeployment } from '../src/emit/dockerfile.js';
import { buildForSpecText, examplePlan, exampleSpecText, planFilesByOwner } from './helpers.js';

/** The example, with its one deployment pointed somewhere other than a container. */
function specWithTarget(target: string): string {
  return exampleSpecText()
    .replace('target: container', `target: ${target}`)
    .replace('streaming: true', 'streaming: false');
}

/** The example plus a second, non-container deployment carrying a secret of its own. */
function specWithSidecar(): string {
  return `${exampleSpecText()}\n  worker:\n    target: batch\n    secrets: [SIDECAR_ONLY]\n`;
}

function plannedPaths(specText: string): string[] {
  return buildForSpecText(specText, 'app.spec.yaml')
    .plan.files.filter((file) => file.owner === 'generated')
    .map((file) => file.path);
}

describe('a container deployment', () => {
  it('plans the image, and only as a generated file', () => {
    expect(hasContainerDeployment(buildForSpecText(exampleSpecText()).ir)).toBe(true);

    const image = examplePlan().files.find((file) => file.path === DOCKERFILE_PATH);
    expect(image?.owner).toBe('generated');
    expect(planFilesByOwner('generated').map((file) => file.path)).toContain(DOCKERFILE_PATH);
  });

  it('runs the application the generator emitted, through exec', () => {
    const { content } = emitDockerfile(buildForSpecText(exampleSpecText()).ir);

    expect(content).toContain('uvicorn app.main:app --host 0.0.0.0 --port');
    // `exec` replaces the shell, so SIGTERM from the platform reaches uvicorn rather than
    // stopping at a shell that does not forward it.
    expect(content).toContain('exec uvicorn');
  });

  it('does not run as root', () => {
    const { content } = emitDockerfile(buildForSpecText(exampleSpecText()).ir);

    expect(content).toMatch(/^USER (?!root)\S+$/m);
    expect(content).not.toMatch(/^USER root$/m);
  });

  it('names a declared secret in prose only, and never makes one a build argument', () => {
    const { content } = emitDockerfile(buildForSpecText(exampleSpecText()).ir);

    const directives = content
      .split('\n')
      .filter((line) => line.trim() !== '' && !line.trimStart().startsWith('#'));

    // The header tells the operator which environment variables to supply; no instruction
    // does, because the process reads them when a model is called.
    expect(content.split('\n').some((line) => line.includes('OPENAI_API_KEY'))).toBe(true);
    expect(directives.some((line) => line.includes('OPENAI_API_KEY'))).toBe(false);
    expect(content).not.toMatch(/^ARG /m);
  });

  it('ignores the secrets of a deployment that is not a container', () => {
    const { content } = emitDockerfile(buildForSpecText(specWithSidecar(), 'app.spec.yaml').ir);

    expect(content).toContain('OPENAI_API_KEY');
    expect(content).not.toContain('SIDECAR_ONLY');
  });

  it('is byte-identical on a second plan', () => {
    const { ir } = buildForSpecText(exampleSpecText());
    expect(emitDockerfile(ir).content).toBe(emitDockerfile(ir).content);
  });

  it('is plain LF text with one trailing newline and no tabs', () => {
    const { content } = emitDockerfile(buildForSpecText(exampleSpecText()).ir);

    expect(content).not.toContain('\r');
    expect(content).not.toContain('\t');
    expect(content.endsWith('\n')).toBe(true);
    expect(content.endsWith('\n\n')).toBe(false);
  });
});

describe('a spec that deploys no container', () => {
  it.each(['batch', 'serverless', 'edge'])('plans %s without an image', (target) => {
    const specText = specWithTarget(target);
    expect(hasContainerDeployment(buildForSpecText(specText, 'app.spec.yaml').ir)).toBe(false);
    expect(plannedPaths(specText)).not.toContain(DOCKERFILE_PATH);
  });
});
